-----------------------------------------------------------------
-- 春节主场景 管理所有 全息投影 物体;
-----------------------------------------------------------------


---@class MapDecryptionHolographicDither
---@field vase                      UnityEngine.Transform -- 参与全息渐影的 花瓶
---@field lantern                   UnityEngine.Transform -- 参与全息渐影的 灯笼
---@field poster                    UnityEngine.Transform -- 参与全息渐影的 福字
---@field fish1                     UnityEngine.Transform -- 参与全息渐影的 鲤鱼(近), 子层含数个 renderer
---@field fish2                     UnityEngine.Transform -- 参与全息渐影的 鲤鱼(远), 子层含数个 renderer
local MapDecryptionHolographicDither = Class('MapDecryptionHolographicDither')

-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Mathf = CS.UnityEngine.Mathf
local Transform = CS.UnityEngine.Transform
local Renderer = CS.UnityEngine.Renderer
local Material = CS.UnityEngine.Material


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local Vector3 = CS.UnityEngine.Vector3



-- ========================================================
-- 一些配置参数:
local thresholdDistance_vase     = 3.5 -- 进入此区域后, 显示全息投影  花瓶
local thresholdDistance_lantern  = 7.0 -- 进入此区域后, 显示全息投影  灯笼
local thresholdDistance_poster   = 6.0 -- 进入此区域后, 显示全息投影  灯笼
local thresholdDistance_fish1 = 4.0 -- 进入此区域后, 显示全息投影  鱼(近)
local thresholdDistance_fish2 = 10.0 -- 进入此区域后, 显示全息投影  鱼(远)

local appearSpeed = 0.7 -- 显示消失的速度

-- ========================================================


function MapDecryptionHolographicDither:__init()
    self.controller = nil
    self.isInit = false
    self.elements = {}
end


function MapDecryptionHolographicDither:__delete()
    for _,e in pairs(self.elements) do 
        for __,m in pairs(e.materials) do
            m = nil -- 释放 material
        end
        e.materials = nil
    end
    self.elements = nil
end



function MapDecryptionHolographicDither:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



function MapDecryptionHolographicDither:Awake()
    KTool.SetActive(self.controller.gameObject, true);

end


function MapDecryptionHolographicDither:Start()
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ================== self ================:  

    self.elements = {} -- list

    self:HandleSingleRenderer( self.vase,    thresholdDistance_vase )
    self:HandleSingleRenderer( self.lantern, thresholdDistance_lantern )
    self:HandleSingleRenderer( self.poster, thresholdDistance_poster )
    self:HandleFish( self.fish1, thresholdDistance_fish1  )
    self:HandleFish( self.fish2, thresholdDistance_fish2 )
end



-- 花瓶,灯笼等 只有一个 renderer, 该用本函数来处理
function MapDecryptionHolographicDither:HandleSingleRenderer( tf, thresholdDistance_ )
    if isNull(tf) then 
        return
    end
    ---@type UnityEngine.Renderer
    local renderer = KTool.GetComponent(tf.gameObject, typeof(Renderer))
    assert( not isNull(renderer) )
    local material_ = renderer.material
    assert( not isNull(material_) )
    self:InsertElement( tf, thresholdDistance_, {material_} )
end



-- fish 内涵数个 renderer 节点, 该用本函数来处理
---@param fishParentTF UnityEngine.Transform
---@param thresholdDistance_ number
function MapDecryptionHolographicDither:HandleFish( fishParentTF, thresholdDistance_ )
    assert( not isNull(fishParentTF) )
    --:
    local materials = {}
    local renderers = fishParentTF:GetComponentsInChildren(typeof(Renderer),true) -- 包含自己
    for i=0, renderers.Length-1 do 
        local renderer = renderers[i]
        assert( not isNull(renderer) )
        local material_ = renderer.material
        assert( not isNull(material_) )
        
        table.insert( materials, material_ )
    end
    --:
    self:InsertElement( fishParentTF, thresholdDistance_, materials )
end


---@param transform_ UnityEngine.Transform
---@param thresholdDistance_ number
---@param materials_  UnityEngine.Material[]
function MapDecryptionHolographicDither:InsertElement( transform_, thresholdDistance_, materials_ )
    local elem = {
        transform = transform_, 
        thresholdDistance = thresholdDistance_, 
        tgtAppear = 0.0,
        lastAppear = 0.0,  -- 上一帧的值, 用来减少 SetFloat() 的调用
        currentAppear = 0.0,
        materials = materials_  -- list
    }
    table.insert( self.elements, elem )
end




---@param roleTF UnityEngine.Transform -- 男女调查官
function MapDecryptionHolographicDither:Init( roleTF_ )
    assert( roleTF_ )
    self.roleTF = roleTF_
    self.isInit = true
end



function MapDecryptionHolographicDither:Update()
    if self.isInit == false then
        return
    end
    ----:
    for _,e in pairs(self.elements) do 
        local distance = (self.roleTF.position - e.transform.position).magnitude -- float
        e.tgtAppear = (distance <= e.thresholdDistance) and 1.0 or -1.0
        ----:
        -- [-1,0] 区间是没太大意义的区间(但不能丢), 所以要快速过度, [0,1] 区间是可视化的区间, 按照预设速度过度:
        local speed = (e.currentAppear < 0.0 and 10.0 or 1.0) * appearSpeed * CS.UnityEngine.Time.deltaTime
        e.currentAppear = Mathf.MoveTowards( e.currentAppear, e.tgtAppear, speed ) -- 匀速过度
        -- 无需每帧都调用 SetFloat() 了;
        if Mathf.Abs(e.currentAppear - e.lastAppear) > 0.003 then 
            e.lastAppear = e.currentAppear
            for __,m in pairs( e.materials ) do 
                m:SetFloat( "_Appear", e.currentAppear )
            end
        end
    end
end

 
return MapDecryptionHolographicDither
